cd /tmp/pw && cat > clamp-check.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({ headless: true });
const p = await b.newPage({ viewport: { width: 1360, height: 1000 } });
await p.goto('http://127.0.0.1:5180/', { waitUntil: 'networkidle' });
await p.evaluate(() => localStorage.clear());
await p.reload({ waitUntil: 'networkidle' });
await p.waitForSelector('.widget');
await p.waitForTimeout(300);
const sel = 'section[aria-label="Выручка по регионам"]';
const rb = await p.locator(`${sel} .widget__resize`).boundingBox();
await p.mouse.move(rb.x + 6, rb.y + 6);
await p.mouse.down();
for (let i = 1; i <= 20; i++) await p.mouse.move(rb.x + 6 + i * 30, rb.y + 6 + i * 20);
await p.waitForTimeout(250);
const during = await p.evaluate((s) => { const r = document.querySelector(s).getBoundingClientRect(); return Math.round(r.right); }, sel);
await p.mouse.up();
await p.waitForTimeout(300);
const after = await p.evaluate((s) => { const r = document.querySelector(s).getBoundingClientRect(); return Math.round(r.right); }, sel);
const gridRight = await p.evaluate(() => Math.round(document.querySelector('.dashboard-grid').getBoundingClientRect().right));
console.log(JSON.stringify({ duringRight: during, afterRight: after, gridRight, stayedPut: during === after, withinGrid: after <= gridRight }));
await b.close();
EOF
export FONTCONFIG_FILE=/tmp/fonts.conf LD_LIBRARY_PATH=$(find /tmp/libs -type d | tr '\n' ':') && timeout 100 node clamp-check.mjs

